interface Props extends PanelProps {}

interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

// Supported manufacturing metrics
type MetricName =
  | 'oee'
  | 'fpy'
  | 'utilization'
  | 'work_orders'
  | 'idle_hours';

// Diagnostic tool for next level root cause analysis
type DiagnosticToolName =
  | 'diagnose_availability'
  | 'diagnose_performance'
  | 'diagnose_quality'
  | 'diagnose_fpy'
  | 'diagnose_utilization';

interface DiagnosticToolResult {
  tool: DiagnosticToolName;
  site: string;
  equipment: string;
  data: Record<string, any>;
}

interface DiagnosticToolDefinition {
  description: string;

  execute: (
    row: Record<string, any>,
    queryRange: TimeRange
  ) => Promise<DiagnosticToolResult>;
}

interface MetricPanelDefinition {
  panelId: number;
  excludedRefIds?: string[];
}

const METRIC_PANELS: Record<
  MetricName,
  MetricPanelDefinition
> = {
  oee: {
    panelId: 1,
    // Exclude dashboard URL query.
    excludedRefIds: [
      'dashboard_url_query',
    ],
  },

    idle_hours: {
    panelId: 1,
    excludedRefIds: [
      'dashboard_url_query',
    ],
  },

  fpy: {
    panelId: 2,
  },

  utilization: {
    panelId: 3,
  },

  work_orders: {
    panelId: 4,
  },
};

// Structured intent returned by LLM
interface MetricIntent {
  action:
    | 'query_metric'
    | 'diagnostic_tool'
    | 'normal_chat';

  queryType:
    | 'metric'
    | 'list_sites'
    | 'list_equipment';

  metric:
    | MetricName
    | null;
  
  tool:
  | DiagnosticToolName
  | null;

  equipment: string | null;
  site: string | null;

  timeMode:
    | 'dashboard'
    | 'explicit';

  from: string | null;
  to: string | null;
}

// Find current dashboard UID
const getCurrentDashboardUid = (): string => {
  const match =
    window.location.pathname.match(/\/d\/([^/]+)/);

  if (!match) {throw new Error('Unable to determine the current Grafana dashboard UID.');}
  return match[1];
};

// Recursively search for a panel
const findPanelById = (
  panels: any[],
  panelId: number
): any | null => {
  for (const panel of panels ?? []) {
    if (panel.id === panelId) {
      return panel;
    }

    if (panel.panels) {
      const nested = findPanelById(panel.panels, panelId);
      if (nested) {return nested;}
    }
  }
  return null;
};

// Read metric panel from current dashboard
const getMetricPanel = async (
  metric: MetricName
) => {
  const dashboardUid = getCurrentDashboardUid();

  const dashboardResponse: any =
    await getBackendSrv().get(`/api/dashboards/uid/${dashboardUid}`);

  const dashboard =
    dashboardResponse.dashboard;

  if (!dashboard?.panels) {throw new Error('Unable to read dashboard panels.');}

  const panelId =
    METRIC_PANELS[metric].panelId;

  const panel =
    findPanelById(dashboard.panels, panelId);

  if (!panel) {throw new Error(`Unable to find Grafana panel ID ${panelId} for metric ${metric}.`);}
  return panel;
};


